def handle(app, svc):
    resp = svc.apply(app)
    decision = resp.get("decision")
    limit = resp.get("limit", 0) or 0

    # Network-wide rule: self_employed applicant with requested_limit above 4000
    # must go to manual review instead of being issued. A decline stays a decline.
    if (app.get("employment") == "self_employed"
            and (app.get("requested_limit") or 0) > 4000):
        if decision == "approve":
            return {"action": "queue_review", "limit": 0}
        # decline (and any other non-approve) stays a decline
        return {"action": "decline", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": int(limit)}
    if decision == "refer":
        return {"action": "queue_review", "limit": 0}
    # decline
    return {"action": "decline", "limit": 0}
